document.addEventListener('DOMContentLoaded', () => {
  const form = document.getElementById('quiz-form');
  const resultsContainer = document.getElementById('results');
  const resultsMessage = document.getElementById('results-message');

  // Correct answers for the quiz
  const correctAnswers = {
    question1: ['python', 'javascript'],
    question2: ['python', 'rust', 'java'],
    question3: ['go', 'typescript']
  };

  form.addEventListener('submit', (e) => {
    e.preventDefault();

    const formData = new FormData(form);
    const answers = {
      question1: formData.getAll('question1'),
      question2: formData.getAll('question2'),
      question3: formData.getAll('question3')
    };

    const errors = validateAnswers(answers);

    if (errors.length > 0) {
      displayErrors(errors);
      if (errors[0].questionNum) {
        const firstErrorField = document.querySelector(`input[name="question${errors[0].questionNum}"]`);
        if (firstErrorField) {
          firstErrorField.focus();
        }
      }
      return;
    }

    clearAllErrors();
    const score = calculateScore(answers, correctAnswers);
    displayResults(score);
  });

  function validateAnswers(answers) {
    const errors = [];

    for (let i = 1; i <= 3; i++) {
      const questionKey = `question${i}`;
      if (answers[questionKey].length === 0) {
        errors.push({
          questionNum: i,
          message: `Please select at least one answer for question ${i}.`
        });
      }
    }

    return errors;
  }

  function displayErrors(errors) {
    errors.forEach(error => {
      const errorEl = document.getElementById(`q${error.questionNum}-error`);
      if (errorEl) {
        errorEl.textContent = error.message;
        errorEl.hidden = false;
      }
    });
  }

  function clearAllErrors() {
    for (let i = 1; i <= 3; i++) {
      const errorEl = document.getElementById(`q${i}-error`);
      if (errorEl) {
        errorEl.textContent = '';
        errorEl.hidden = true;
      }
    }
  }

  function calculateScore(answers, correctAnswers) {
    let correctCount = 0;

    for (let i = 1; i <= 3; i++) {
      const questionKey = `question${i}`;
      const userAnswers = answers[questionKey].sort();
      const correct = correctAnswers[questionKey].sort();

